def hidden_rule_fn(state):
    # Extract particles
    particles = list(state)  # list of dicts with 'type', 'x', 'y'

    # Separate PLEKTs and WOVVEs
    plekts = [p for p in particles if p['type'] == 'PLEKT']
    wovves = [p for p in particles if p['type'] == 'WOVVE']

    def wrap_diff(a, b):
        """Compute wrapped difference b - a on 8-torus."""
        d = (b - a) % 8
        if d > 4:
            d -= 8
        return d

    def wovve_dist(p1, p2):
        """Asymmetric distance: |wrap_dx|^2 + |wrap_dy|."""
        dx = wrap_diff(p1['x'], p2['x'])
        dy = wrap_diff(p1['y'], p2['y'])
        return abs(dx)**2 + abs(dy)

    def chebyshev_step(from_p, to_p):
        """One Chebyshev step toward to_p."""
        dx = wrap_diff(from_p['x'], to_p['x'])
        dy = wrap_diff(from_p['y'], to_p['y'])
        step_x = 0
        step_y = 0
        if dx > 0:
            step_x = 1
        elif dx < 0:
            step_x = -1
        if dy > 0:
            step_y = 1
        elif dy < 0:
            step_y = -1
        return ((from_p['x'] + step_x) % 8, (from_p['y'] + step_y) % 8)

    def chebyshev_step_away(from_p, to_p):
        """One Chebyshev step away from to_p."""
        dx = wrap_diff(from_p['x'], to_p['x'])
        dy = wrap_diff(from_p['y'], to_p['y'])
        step_x = 0
        step_y = 0
        if dx > 0:
            step_x = -1
        elif dx < 0:
            step_x = 1
        if dy > 0:
            step_y = -1
        elif dy < 0:
            step_y = 1
        return ((from_p['x'] + step_x) % 8, (from_p['y'] + step_y) % 8)

    # Track which positions are occupied in original state
    occupied = set()
    for p in particles:
        occupied.add((p['x'], p['y'], p['type']))

    # Compute new positions for PLEKTs
    new_positions = {}  # (x, y) -> (type, new_x, new_y)

    for p in plekts:
        if not wovves:
            # No WOVVEs, PLEKT stays
            new_positions[(p['x'], p['y'])] = ('PLEKT', p['x'], p['y'])
        else:
            # Find nearest WOVVE by wovve_dist
            nearest_w = min(wovves, key=lambda w: wovve_dist(p, w))
            new_x, new_y = chebyshev_step(p, nearest_w)
            new_positions[(p['x'], p['y'])] = ('PLEKT', new_x, new_y)

    # Compute new positions for WOVVEs
    for p in wovves:
        if len(wovves) == 1:
            # Single WOVVE: move away from nearest PLEKT if close
            if plekts:
                nearest_p = min(plekts, key=lambda pl: wovve_dist(p, pl))
                dist = wovve_dist(p, nearest_p)
                if dist < 2:
                    new_x, new_y = chebyshev_step_away(p, nearest_p)
                    new_positions[(p['x'], p['y'])] = ('WOVVE', new_x, new_y)
                else:
                    new_positions[(p['x'], p['y'])] = ('WOVVE', p['x'], p['y'])
            else:
                new_positions[(p['x'], p['y'])] = ('WOVVE', p['x'], p['y'])
        else:
            # Multiple WOVVEs: move toward nearest WOVVE
            nearest_w = min([w for w in wovves if w is not p], key=lambda w: wovve_dist(p, w))
            new_x, new_y = chebyshev_step(p, nearest_w)
            new_positions[(p['x'], p['y'])] = ('WOVVE', new_x, new_y)

    # Spawn WOVVEs at anti-poles
    # Spawn condition: anti-pole unoccupied in original state
    for p in wovves:
        anti_x = (p['x'] + 4) % 8
        anti_y = (p['y'] + 4) % 8
        if (anti_x, anti_y, 'PLEKT') not in occupied and (anti_x, anti_y, 'WOVVE') not in occupied:
            new_positions[(anti_x, anti_y)] = ('WOVVE', anti_x, anti_y)

    # Build result list
    result = []
    for key, (ptype, nx, ny) in new_positions.items():
        result.append({'type': ptype, 'x': nx, 'y': ny})

    return result
